UPDATE product_sku
SET status = #{status}, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}

UPDATE product_sku
SET is_default = 1, updated_at = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
